package com.hospital.system.controller;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import com.hospital.system.service.HospitalService;
@RestController @RequestMapping("/api/services") public class ServiceController { private final HospitalService s; public ServiceController(HospitalService s){this.s=s;} @GetMapping public Object all(){return s.all();} @GetMapping("/{id}") public com.hospital.system.model.HospitalService one(@PathVariable Long id){return s.one(id);} @PostMapping public ResponseEntity<com.hospital.system.model.HospitalService> add(@RequestBody com.hospital.system.model.HospitalService x){return ResponseEntity.status(201).body(s.add(x));} @PutMapping("/{id}") public com.hospital.system.model.HospitalService update(@PathVariable Long id,@RequestBody com.hospital.system.model.HospitalService x){return s.update(id,x);} @DeleteMapping("/{id}") public ResponseEntity<Void> del(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();} }
